function coverFor(p){
 if(Object.prototype.hasOwnProperty.call(EDITORIAL_COVERS,p.slug))return EDITORIAL_COVERS[p.slug];
 if(p.cover_image_url)return p.cover_image_url;
 if(p.category!=="diario")return "";
 // Foto solo nei capitoli illustrati: niente ripetizione automatica su ogni scheda.
 const dated=p.slug?.slice(-10)||"";
 const illustrated=new Set(["2026-03-20","2026-04-18","2026-07-31","2026-08-01","2026-10-01","2026-11-11","2026-11-18"]);
 if(!illustrated.has(dated))return "";
 return ["2026-04-18","2026-11-18"].includes(dated)?"/media/illustrations/nadir-keyboard.webp":"/media/illustrations/que-nadir-garage.webp";
}
function displayTitle(p){
 return p.category==="diario"?p.title.replace(/^\d{2}\/\d{2}\/\d{4}\s*[—-]\s*/,""):p.title;
}
function thematicTile(p){
 const key=(p.tags||[]).find(t=>!["diario","fatti","intermezzo","bikerlink"].includes(t))||"garage";
 const accepted=["matching","gps","telemetry","build","database","ai","chat","security","sos","music","infra","ui","clubs","quality","email","translation","ottobre","garage"];
 const type=accepted.includes(key)?key:"garage";
 const symbol={matching:"↔",gps:"⌖",telemetry:"∿",build:"⌘",database:"▤",ai:"◇",chat:"◌",security:"⊡",sos:"✚",music:"♫",infra:"▥",ui:"▦",clubs:"◎",quality:"✓",email:"✉",translation:"言",ottobre:"!",garage:"⚙"}[type];
 return '<div class="poster poster-'+type+'"><span class="poster-code">BIKERLINK / '+esc(type.toUpperCase())+'</span><span class="poster-symbol">'+symbol+'</span><span class="poster-date">'+esc((p.slug||"").slice(-10))+'</span></div>';
}
function cardExcerpt(p){
 if(p.category!=="diario")return excerpt(p.excerpt);
 const generic=/una giornata del laboratorio BikerLink|Intermezzo dal garage/i.test(p.excerpt||"");
 if(!generic)return excerpt(p.excerpt);
 const paragraphs=p.content.split(/\n\s*\n/).filter(s=>s.trim());
 const evidence=paragraphs.find(x=>x.startsWith("Il dettaglio concreto che rende questa storia diversa"));
 const sources=evidence?[...evidence.matchAll(/«([^»]{10,150})»/g)].map(m=>m[1]):[];
 if(sources.length){
  const names=sources.slice(0,2).map(x=>x.length>100?x.slice(0,96)+"…":x);
  const starts=[
   "Quella giornata il codice si occupa di ",
   "Tra i lavori documentati troviamo ",
   "La parte concreta del racconto riguarda ",
   "La cronologia tecnica segnala ",
   "Il problema affrontato passa da ",
   "Sul banco del garage finiscono "
  ];
  const prefix=starts[p.id%starts.length];
  return esc(prefix+names.map(x=>"«"+x+"»").join(" e ")+". Una giornata di prove e di domande, non una funzione dichiarata perfetta.");
 }
 const focus=paragraphs.find((p,i)=>i>1&&!p.startsWith("##")&&!p.startsWith("Nel nostro racconto")&&!p.startsWith("C'è una distinzione")&&p.length>90)||
 paragraphs.find(p=>p.length>100&&!p.startsWith("##"))||p.excerpt;
 let sentence=focus.replace(/\*\*/g,"").replace(/\n/g," ").replace(/\s+/g," ").trim();
 if(sentence.length>210)sentence=sentence.slice(0,210).replace(/\s+\S*$/,"")+"…";
 return esc(sentence+(p.tags?.includes("intermezzo")?" · Riflessione narrativa, senza commit attribuiti alla giornata.":""));
}
function card(p){const cover=coverFor(p);return '<a class="tile" href="/posts/'+encodeURIComponent(p.slug)+'">'+(cover?'<img loading="lazy" referrerpolicy="no-referrer" src="'+attrs(cover)+'" alt="Illustrazione del garage di BikerBlog">':p.category==="diario"?thematicTile(p):'')+'<div class="pad"><span class="pill">'+esc(p.category)+'</span><h2>'+esc(displayTitle(p))+'</h2><p>'+cardExcerpt(p)+'</p><small class="meta">'+date(p.published_at)+' · '+esc(AUTHORS.get(p.author_id)?.name||"BikerBlog")+'</small></div></a>';}
function listing(title,arr,desc){return '<section class="intro"><span class="eyebrow">BikerBlog · Archivio</span><h1>'+esc(title)+'</h1><p class="subtitle">'+esc(desc||arr.length+" articoli recuperati dal repository storico.")+'</p></section><form class="search" action="/posts"><input name="q" type="search" placeholder="Cerca negli articoli..." aria-label="Cerca negli articoli"><button>Cerca</button></form><div class="grid">'+(arr.length?arr.map(card).join(""):"<p>Nessun articolo trovato.</p>")+'</div>';}
function timelinePage(){
const sorted=[...POSTS].sort((a,b)=>Date.parse(b.published_at)-Date.parse(a.published_at));
const grouped=new Map();
for(const p of sorted){
 const month=new Date(p.published_at).toLocaleDateString("it-IT",{month:"long",year:"numeric"});
 if(!grouped.has(month))grouped.set(month,[]);
 grouped.get(month).push(p);
}
return '<section class="intro"><span class="eyebrow">BikerBlog / archivio cronologico</span><h1>La timeline della nostra follia.</h1><p class="subtitle">Un evento dopo l\'altro, non 250 copie della stessa fotografia. Qui si segue la cronologia: data, voce, problema tecnico e racconto.</p></section><div class="paper-note">Le giornate ricostruite sono distinte dagli articoli storici. Il diario è una retrospettiva: non una cronologia di pubblicazioni effettivamente giornaliere.</div>'
+[...grouped.entries()].map(([label,items])=>'<section class="month-section"><h2 class="month-heading">'+esc(label)+'<span class="month-count">'+items.length+' storie</span></h2><div class="timeline-entries">'+items.map((p,i)=>{
const isDiary=p.category==="diario";
const sourceTag=isDiary?(p.tags?.includes("intermezzo")?"INTERMEZZO NARRATIVO":"DIARIO TECNICO"):"ARCHIVIO ORIGINALE";
return '<a class="chronicle-row" href="/posts/'+encodeURIComponent(p.slug)+'"><div class="chronicle-date">'+new Date(p.published_at).toLocaleDateString("it-IT",{day:"2-digit",month:"short"})+'</div><div class="chronicle-detail"><span class="pill">'+sourceTag+' · '+esc(AUTHORS.get(p.author_id)?.name||"BikerBlog")+'</span><h3>'+esc(p.title.replace(/^\d{2}\/\d{2}\/\d{4}\s*[—-]\s*/,""))+'</h3><p>'+cardExcerpt(p)+'</p><span class="meta">'+Number(p.reading_minutes||3)+' MIN · LEGGI IL CAPITOLO</span></div></a>';}).join("")+'</div></section>').join("");
}
function diaryIndex(authorKey=""){
const all=POSTS.filter(p=>p.category==="diario").sort((a,b)=>Date.parse(b.published_at)-Date.parse(a.published_at));
const selected=ARCHIVE.authors.some(a=>String(a.id)===String(authorKey))?String(authorKey):"";
const entries=selected?all.filter(p=>String(p.author_id)===selected):all;
const filters='<div class="author-filters"><a href="/diario" class="'+(!selected?"active":"")+'">Tutte le voci</a>'+ARCHIVE.authors.map(a=>'<a href="/diario?autore='+a.id+'" class="'+(selected===String(a.id)?"active":"")+'">'+esc(a.name)+'</a>').join("")+'</div>';
const groups=new Map();
for(const p of entries){const month=new Date(p.published_at).toLocaleDateString("it-IT",{month:"long",year:"numeric"});if(!groups.has(month))groups.set(month,[]);groups.get(month).push(p);}
const months=[...groups.entries()].map(([label,arr])=>'<section class="month-section"><h2 class="month-heading">'+esc(label)+' <span class="month-count">'+arr.length+' giornate</span></h2>'+arr.map((p,i)=>'<a class="day-row" href="/posts/'+encodeURIComponent(p.slug)+'"><div class="day-stamp">'+esc(new Date(p.published_at).toLocaleDateString("it-IT",{day:"2-digit"}))+'</div><div>'+(i%5===0?'<img class="daythumb" loading="lazy" src="'+attrs(coverFor(p))+'" alt="Scena del garage">':'')+'<span class="pill">'+esc(AUTHORS.get(p.author_id)?.name||"BikerBlog")+'</span><h3>'+esc(p.title.replace(/^\d{2}\/\d{2}\/\d{4}\s*[—-]\s*/,""))+'</h3><p>'+esc(p.excerpt)+'</p><span class="meta">LEGGI LA GIORNATA · '+Number(p.reading_minutes||2)+' MIN</span></div></a>').join("")+'</section>').join("");
return '<section class="intro"><span class="eyebrow">Cronache del garage</span><h1>235 giorni. Un garage. Troppi bug.</h1><p class="subtitle">Mendo, L’Agente, Quebracho e Nadir — Maine Coon di dieci chili, Verme delle Sabbie e parente di Galactus. I guai sono veri. Le conversazioni domestiche, quando non documentate, sono inventate.</p></section><div class="paper-note"><strong>Nota di redazione.</strong> Ogni giornata ha i suoi riferimenti tecnici; le date della perdita dati di ottobre sono convenzionali finché non avremo una cronologia verificata. Non fingiamo di aver tenuto un diario in tempo reale.</div><div class="diary-topline"><span class="diary-count">'+entries.length+' giornate · '+all.length+' nel diario completo</span></div>'+filters+(months||"<p>Nessuna giornata per questo autore.</p>");
}
function galleryPage(){
return '<section class="intro"><span class="eyebrow">Una redazione a quattro zampe</span><h1>Il garage e i suoi inquilini.</h1><p class="subtitle">Quebracho, pastore svizzero bianco, presidia il banco di prova. Nadir, Maine Coon red tabby di dieci chili, gestisce la disponibilità delle crocchette. Le immagini sono mockup narrativi, non fotografie scattate durante lo sviluppo.</p></section><div class="gallery-grid"><figure><img src="/media/illustrations/que-nadir-garage.webp" alt="Quebracho pastore svizzero bianco, Nadir Maine Coon rosso, moto e tastiere"><figcaption>Il reparto sicurezza e il responsabile alimentare.</figcaption></figure><figure><img src="/media/illustrations/nadir-keyboard.webp" alt="Maine Coon rosso su tastiera con cavi e motociclette"><figcaption>Nadir, il Verme delle Sabbie, dopo aver assunto il controllo della tastiera.</figcaption></figure></div><div class="paper-note">Sono illustrazioni di atmosfera: gli episodi domestici del diario sono ricostruzioni comiche, non registrazioni fotografiche degli eventi.</div>';
}
function home(){
const p=POSTS[0],diary=POSTS.filter(x=>x.category==="diario"),archive=POSTS.filter(x=>x.category!=="diario"),heroCover=p?coverFor(p):"";
const feature=p?'<section class="feature '+(heroCover?"":"no-image")+'">'+(heroCover?'<img src="'+attrs(heroCover)+'" alt="Scena del garage di BikerBlog">':"")+'<div class="pad"><span class="eyebrow">Dal diario · '+date(p.published_at)+'</span><h2>'+esc(p.title.replace(/^\d{2}\/\d{2}\/\d{4}\s*[—-]\s*/,""))+'</h2><p>'+excerpt(p.excerpt)+'</p><p class="meta">A CURA DI '+esc(AUTHORS.get(p.author_id)?.name||"BikerBlog")+'</p><a href="/posts/'+encodeURIComponent(p.slug)+'" class="read">Leggi la giornata</a></div></section>':"";
return '<section class="intro"><span class="eyebrow">BIKERBLOG / appunti da un garage improbabile</span><h1>Le storie dietro<br>ogni chilometro.</h1><p class="subtitle">Non un comunicato stampa. Il diario di un programmatore alle prime armi, di Rei, di un cane che annusa i bug e di Nadir, il Verme delle Sabbie da dieci chili che annusa soprattutto il cibo.</p><div class="diary-topline"><span class="diary-count">'+diary.length+' GIORNATE DEL DIARIO</span><span class="diary-count">'+archive.length+' ARTICOLI STORICI</span><span class="diary-count">FATTI TECNICI + SCENE NARRATIVE</span></div></section>'+feature+'<div class="split-heading"><h2>Il diario, giorno dopo giorno</h2><a href="/diario">Apri la cronologia completa</a></div><div class="grid">'+diary.filter(x=>x.slug!==p?.slug).slice(0,6).map(card).join("")+'</div><div class="split-heading"><h2>Dall’archivio originale</h2><a href="/posts">Tutti gli articoli</a></div><div class="grid">'+archive.slice(0,3).map(card).join("")+'</div>';
}
function article(p){
const a=AUTHORS.get(p.author_id);const cs=ARCHIVE.comments.filter(c=>c.post_id===p.id);
const isDiary=p.category==="diario",cover=coverFor(p);
return '<article class="article"><span class="pill">'+esc(p.category)+'</span><h1>'+esc(displayTitle(p))+'</h1>'+(isDiary?'':'<p class="subtitle">'+excerpt(p.excerpt)+'</p>')+'<p class="meta">'+date(p.published_at)+' · '+esc(a?.name||"BikerBlog")+' · '+Number(p.reading_minutes||5)+' minuti</p>'+(cover?'<figure class="garage-photo"><img class="cover" loading="lazy" src="'+attrs(cover)+'" alt="Raffigurazione del pastore svizzero Quebracho e del Maine Coon Nadir fra moto e computer"><figcaption>Scena illustrata dal garage · immagine ricostruita, non fotografia documentale</figcaption></figure>':'')+'<div class="body">'+markdown(p.content)+'</div>'+(p.tags?.length?'<div class="tags">'+p.tags.map(t=>'<a href="/tags/'+encodeURIComponent(t)+'">#'+esc(t)+'</a>').join("")+'</div>':'')+(cs.length?'<section><h2>Commenti storici ('+cs.length+')</h2>'+cs.map(c=>'<p><strong>'+esc(c.author_name||c.authorName||"Lettore")+'</strong> · '+esc(c.content||c.body||"")+'</p>').join("")+'</section>':'')+'<p class="author-signature">'+(isDiary?"Cronaca editoriale: fonti tecniche esplicite, battute e scene immaginate.":"Articolo originale dell’archivio storico.")+'</p><p><a class="read" href="'+(isDiary?"/diario":"/posts")+'">← Torna '+(isDiary?"al diario":"agli articoli")+'</a></p></article>';
}
function response(body,status=200,ct="text/html; charset=utf-8"){return new Response(body,{status,headers:{"content-type":ct,"x-content-type-options":"nosniff","referrer-policy":"strict-origin-when-cross-origin","cache-control":"public, max-age=120","content-security-policy":"default-src 'none'; style-src 'unsafe-inline'; img-src https: data:; form-action 'self'; base-uri 'none'; frame-ancestors 'none'"}});}
